  "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
];

export default function Planillas({
  planillas = [],
  periodos = [],
  empleados = [],
  nuevaPlanilla = {},
  setNuevaPlanilla,
  planillaCargado,
  crearPlanilla,
  actualizarPlanilla,
  eliminarPlanilla,
  cargarPlanilla,
  limpiarFormularioPlanilla,
  verDetalle,
  vistaDetalle,
  planillaSeleccionada,
  volverAListado
}) {

  const [periodoFiltroTabla, setPeriodoFiltroTabla] = useState("");

  if (vistaDetalle) {
    return (
      <DetallePlanilla
        planilla={planillaSeleccionada}
        empleados={empleados}
        periodos={periodos}
        onVolver={volverAListado}
      />
    );
  }

  const periodoSeleccionado = periodos.find(p => p.id === parseInt(nuevaPlanilla.periodo_id));
  const mesSeleccionado = periodoSeleccionado?.mes;

  const mostrarAguinaldo = mesSeleccionado && [10, 11, 12].includes(mesSeleccionado);
  const añoSeleccionado = periodoSeleccionado?.año;
  const mostrarQuincena25 = mesSeleccionado === 1 && añoSeleccionado >= 2026;

  const planillasFiltradas = Array.isArray(planillas) 
    ? planillas.filter((pl) => {
        if (periodoFiltroTabla === "") return true;
        return Number(pl.periodo_id) === Number(periodoFiltroTabla);
      })
    : [];

  return (
    <>
      {/* 🔥 HEADER REEMPLAZADO POR COMPONENTE */}
      <PageHeader title="Registro de Planillas" />

      <div style={{ padding: "30px 20px", background: "#f5f5f5" }}>
        <div style={{ maxWidth: "1200px", margin: "auto" }}>
          
          {/* ===== FORMULARIO ===== */}
          <div
            style={{
              background: "white",
              borderRadius: "16px",
              boxShadow: "0 8px 30px rgba(0,0,0,0.08)",
              padding: "30px 35px",
              marginBottom: "30px",
            }}
          >
            <h2 style={{ marginBottom: "25px", color: "#d71920", fontSize: "24px" }}>
              {planillaCargado ? "✏️ Editar Planilla" : "📝 Registrar Nueva Planilla"}
            </h2>

            <form onSubmit={planillaCargado ? actualizarPlanilla : crearPlanilla}>
              
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px", marginBottom: "20px" }}>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Período</label>
                  <select
                    value={nuevaPlanilla.periodo_id}
                    onChange={(e) =>
                      setNuevaPlanilla({ ...nuevaPlanilla, periodo_id: e.target.value })
                    }
                    required
                    style={{
                      width: "100%",
                      padding: "10px 12px",
                      borderRadius: "8px",
                      border: "1px solid #ddd",
                    }}
                  >
                    <option value="">Seleccione período</option>
                    {periodos.map((per) => (
                      <option key={per.id} value={per.id}>
                        {meses[per.mes - 1]}/{per.año}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Empleado</label>
                  <select
                    value={nuevaPlanilla.empleado_id}
                    onChange={(e) =>
                      setNuevaPlanilla({ ...nuevaPlanilla, empleado_id: e.target.value })
                    }
                    required
                    style={{
                      width: "100%",
                      padding: "10px 12px",
                      borderRadius: "8px",
                      border: "1px solid #ddd",
                    }}
                  >
                    <option value="">Seleccione empleado</option>
                    {empleados.map((emp) => (
                      <option key={emp.id} value={emp.id}>
                        {emp.nombre} - DUI: {emp.dui} - {emp.puesto}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px", marginBottom: "20px" }}>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Sueldo base mensual (USD)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={nuevaPlanilla.sueldo_base || ""}
                    readOnly
                    onFocus={(e) => e.target.select()}
                    onChange={(e) =>
                      setNuevaPlanilla({
                        ...nuevaPlanilla,
                        sueldo_base: parseFloat(e.target.value) || 0,
                      })
                    }
                    required
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>

                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Subsidio de alimentación (USD)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={nuevaPlanilla.subsidio_alimentacion || ""}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) =>
                      setNuevaPlanilla({
                        ...nuevaPlanilla,
                        subsidio_alimentacion: parseFloat(e.target.value) || 0,
                      })
                    }
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px", marginBottom: "20px" }}>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Horas extra diurnas</label>
                  <input
                    type="number"
                    step="0.5"
                    value={nuevaPlanilla.horas_extras_diurnas || ""}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) =>
                      setNuevaPlanilla({
                        ...nuevaPlanilla,
                        horas_extras_diurnas: parseFloat(e.target.value) || 0,
                      })
                    }
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>

                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Horas extra nocturnas</label>
                  <input
                    type="number"
                    step="0.5"
                    value={nuevaPlanilla.horas_extras_nocturnas || ""}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) =>
                      setNuevaPlanilla({
                        ...nuevaPlanilla,
                        horas_extras_nocturnas: parseFloat(e.target.value) || 0,
                      })
                    }
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px", marginBottom: "20px" }}>
                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Bono extra (USD)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={nuevaPlanilla.bono_extra || ""}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) =>
                      setNuevaPlanilla({
                        ...nuevaPlanilla,
                        bono_extra: parseFloat(e.target.value) || 0,
                      })
                    }
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>

                <div>
                  <label style={{ fontWeight: "600", display: "block", marginBottom: "6px" }}>Descuentos adicionales (USD)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={nuevaPlanilla.descuentos_adicionales || ""}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) =>
                      setNuevaPlanilla({
                        ...nuevaPlanilla,
                        descuentos_adicionales: parseFloat(e.target.value) || 0,
                      })
                    }
                    style={{ width: "100%", padding: "10px 12px", borderRadius: "8px", border: "1px solid #ddd" }}
                  />
                </div>
              </div>

              <div style={{ display: "flex", flexDirection: "column", gap: "12px", marginBottom: "20px" }}>
                {mostrarAguinaldo && (
                  <label>
                    <input
                      type="checkbox"
                      checked={nuevaPlanilla.pagar_aguinaldo || false}
                      onChange={(e) =>
                        setNuevaPlanilla({
                          ...nuevaPlanilla,
                          pagar_aguinaldo: e.target.checked,
                        })
                      }
                    />
                    Pagar Aguinaldo
                  </label>
                )}

                {mostrarQuincena25 && (
                  <label>
                    <input
                      type="checkbox"
                      checked={nuevaPlanilla.quincena25_aplica || false}
                      onChange={(e) =>
                        setNuevaPlanilla({
                          ...nuevaPlanilla,
                          quincena25_aplica: e.target.checked,
                        })
                      }
                    />
                    Pagar Quincena 25
                  </label>
                )}
              </div>

              <div style={{ display: "flex", gap: "12px", marginTop: "10px" }}>
                <button type="submit" style={{ background: "#d71920", color: "white", flex: 1 }}>
                  {planillaCargado ? "Actualizar" : "Registrar"}
                </button>

                <button type="button" onClick={limpiarFormularioPlanilla}>
                  Limpiar
                </button>
              </div>
            </form>
          </div>

          {/* ===== TABLA ===== */}
          <div style={{ background: "white", padding: "20px", borderRadius: "16px" }}>
            <h3>📋 Planillas Registradas</h3>

            <div style={{ marginBottom: "10px" }}>
              <select
                value={periodoFiltroTabla}
                onChange={(e) => setPeriodoFiltroTabla(e.target.value)}
              >
                <option value="">Mostrar todo</option>
                {periodos.map((per) => (
                  <option key={per.id} value={per.id}>
                    {meses[per.mes - 1]}/{per.año}
                  </option>
                ))}
              </select>
            </div>

            <table style={{ width: "100%" }}>
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Empleado</th>
                  <th>Período</th>
                  <th>Neto</th>
                  <th>Acciones</th>
                </tr>
              </thead>

              <tbody>
                {planillasFiltradas.map((pl) => {
                  const emp = empleados.find((e) => e.id === pl.empleado_id);
                  const per = periodos.find((p) => p.id === pl.periodo_id);

                  return (
                    <tr key={pl.id}>
                      <td>{pl.id}</td>
                      <td>{emp?.nombre || "?"}</td>
                      <td>{per ? `${meses[per.mes - 1]}/${per.año}` : "?"}</td>
                      <td>${pl.monto_neto?.toFixed(2)}</td>
                      <td>
                        <button onClick={() => verDetalle(pl)}>Detalle</button>
                        <button onClick={() => cargarPlanilla(pl)}>Editar</button>
                        <button onClick={() => eliminarPlanilla(pl.id)}>Eliminar</button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </>
  );
}
